data.value:
.container{
    padding: 6px 14px 20px 14px;
} 
.popup{
	width: 362px;
	height: auto;
	padding: 4px;
	border-radius: 4px;
    box-shadow: 0px 8px 16px rgba(0,0,0,0.25);
    border: 1px solid @WindowText/0.2;
    display: flex;
    flex-direction: column;
    font-family: "Segoe UI";
    text-align: center;
    justify-content: space-around;
    background-color: @Control;
	color: @ControlText;
	font-size: 10pt;
}
.header{
	display: flex;
	flex-direction: row;
	justify-content: space-between;
	font-family: 'Segoe UI Semibold';
}
.header-caption{
	padding: 10px 10px 0px 10px;
	display: flex;
	flex-direction: row;
}
.header-caption-icon{
	width: 18px;
	height: 18px;
}
.header-caption-text{
	padding-left: 10px;
}
.header-buttons{
	display: flex;
	flex-direction: row;
	padding: 5px 2px 0px 0px;
}
.header-button{
	padding: 5px;
	border-radius: 2px;
	align-self: center;
}
.header-button:hover{
	background-color: @HotTrackedColor/0.9;
}
.header-button:active{
	background-color: @HotTrackedColor/0.6;
}
.close-button{
	width: 18px;
	height: 18px;
}
.message{
	display: flex;
	flex-direction: row;
}
.message-text-container{
	text-align: left;
	padding: 10px;
}
.message-image-container{
	align-self: center;
	padding: 9px;
}
.message-image{
	width: 54px;
	height: 54px;
}
.message-caption{
	font-size: 10.5pt;
	font-family: 'Segoe UI Semibold';
}
.message-text{
}
.buttons{
	display: flex;
	flex-direction: row;
	justify-content: space-between;
}
.button{
	margin: 9px;
	padding: 8px;
	width: 100%;
	border-radius: 4px;
	box-shadow: 1px 1px 1px rgba(0,0,0,0.25);
    background-color: @Window;
    color: @WindowText;
    font-size: 10.5pt;
    font-family: 'Segoe UI Semibold';
    border: 1px solid @WindowText/0.1;

}
.button:hover{
	background-color: @HotTrackedColor/0.9;
	color: @HotTrackedForeColor;
	border: 1px solid @HotTrackedForeColor/0.2;
}
.button:active{
	background-color: @HotTrackedColor/0.6;
}

.container{
	width: 378px;
	height: auto;
	padding: 7px 12px 12px 7px;
}
.popup{
	background-color: @Window/0.95;
	border-radius: 6px;
	border-style: solid;
	border-width: 1px 1px 1px 0px;
	/*You can change this color to any RGBA value or skinned color (for example, "@Warning").
	If this value is "@Black", the custom demo code replaces this color with the primary color of the notification icon.*/
	box-shadow: 2px 2px 12px @Black/0.2;
	border-color: @Black/0.3;
	display: flex;
	flex-direction: row;
}
.content{
	width: 100%;
	display: flex;
	flex-direction: row;
	align-items: center;
	background-color: @Black/0.015;
}
.stripe{
	width: 3px;
	background-color: @Black/0.8;
	height: 100%;
	border-radius: 6px 0px 0px 6px;
}
.message{
	display: flex;
	flex-direction: column;
	padding: 8px;
	font-family: 'Segoe UI';
	color: @WindowText;
}
.icon-container{
	padding: 8px;
}
.icon{
	width: 22px;
	height: 22px;
}
.caption{
	font-size: 11pt;
	font-weight: bold;
	padding: 6px;
}
.text{
	font-size: 10.5pt;
	padding: 0px 6px 6px 6px;
}
.close-button{
	padding: 8px;
	border-radius: 4px 0px 0px 4px;
}
.close-button:hover{
	background-color: @Black/0.1;
}
.close-button:active{
	background-color: @Black/0.2;
}
.close-icon{
	width: 22px;
	height: 22px;
}

.container{
    padding: 5px 12px 12px 5px;
} 
.popup{
	width: 274px;
	height: auto;
	padding: 12px;
	background-color: @Window;
    border-radius: 6px;
    box-shadow: 3px 3px 10px rgba(0,0,0,0.2);
    display: flex;
    flex-direction: column;
    color: @WindowText;
    font-family: "Segoe UI";
    text-align: center;
    justify-content: space-around;
    border: 1px solid @Control;
}
.image{
	width: 48px;
	height: 48px;
	align-self: center;
}
.caption{
	padding: 4px;
	font-size: 11.5pt;
	font-weight: bold;
}
.text{   
	padding: 4px;   
    font-size: 10pt;
}
.ok-button{
	margin: 12px 3px 3px 3px;
	padding: 6px;
	width: 60px;
    color: @White;
    background-color: @Primary;
    border-radius: 3px;
    font-size: 16px;
    align-self: center;
}
.ok-button:hover{
	background-color: @Primary/0.8;
}
.ok-button:active{
	background-color: @Primary/0.6;
}

.container{
    padding: 6px 16px 16px 6px;
} 
.popup{
	width: 290px;
	padding: 2px 12px 2px 12px;
	background-color: rgba(0,0,0,0.7);
    border-radius: 10px;
    box-shadow: 4px 4px 12px rgba(0,0,0,0.2);
    display: flex;
    flex-direction: row;
    justify-content: space-between;
    font-family: "Open Sans", sans-serif;
    color: #F5F5F5;
}
.text{     
	padding: 10px; 
    font-size: 10pt;
    word-wrap: break-word;
}
.close-button{
	padding: 7px 10px 7px 10px;
    font-size: 11pt;
	font-weight: bold;
	align-self: center;
}
.close-button:hover{
	color: rgba(0,0,0,0.7);
	background-color: #F5F5F5;
	border-radius: 8px;
	box-shadow: 0px 0px 4px rgba(255,255,255,0.3);
}
.close-button:active{
	background-color: #E5E5E5;
}
